<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS encaissements (id INT AUTO_INCREMENT PRIMARY KEY,facture_id INT NOT NULL,montant DECIMAL(15,2) NOT NULL,date_encaissement DATE NOT NULL,reference_paiement VARCHAR(150),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_payment_invoice(facture_id),INDEX idx_payment_date(date_encaissement)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
